/**
 * The AuthenticationManager handle basic HTTP authentication.
 * 
 * @author Tim Roes
 */
public class AuthenticationManager {

	private String user;
	private String pass;

	/**
	 * Clear the username and password. No basic HTTP authentication will be used
	 * in the next calls.
	 */
	public void clearAuthData() {
		this.user = null;
		this.pass = null;
	}

	/**
